<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{teacherAPI}from'../../api/teacher';import type{Binding,BindingAdapter,Model,ModelCategory,ModelStatus,Provider}from'../../api/types';import{APIError}from'../../api/client';import StatusBadge from'../../components/StatusBadge.vue';import AppDialog from'../../components/AppDialog.vue';import{useToast}from'../../composables/useToast';const rows=ref<Model[]>([]),providers=ref<Provider[]>([]),tab=ref<'common'|'all'>('common'),query=ref(''),category=ref(''),status=ref(''),selected=ref<{model:Model;bindings:Binding[]}|null>(null),createOpen=ref(false),bindingOpen=ref(false),editingBinding=ref<Binding|null>(null),capability=ref(''),error=ref(''),routingModels=ref<string[]>([]),toast=useToast(),route=useRoute(),router=useRouter();const filtered=computed(()=>rows.value.filter(m=>(tab.value==='all'||m.is_common)&&(!query.value||`${m.display_name} ${m.model_id}`.toLowerCase().includes(query.value.toLowerCase()))&&(!category.value||m.category===category.value)&&(!status.value||m.status===status.value)).sort((a,b)=>a.display_name.localeCompare(b.display_name)));const pending=computed(()=>rows.value.filter(m=>m.status==='pending_configuration').length);const modelForm=reactive({model_id:'',display_name:'',description:'',category:'text' as ModelCategory,capabilities:[] as string[],input_modalities:[] as string[],output_modalities:[] as string[],context_window:null as number|null,max_output_tokens:null as number|null,is_common:false,status:'pending_configuration' as ModelStatus});const bindingForm=reactive({provider_id:'',upstream_model_name:'',adapter:'openai_compatible' as BindingAdapter,priority:100,status:'active' as'active'|'inactive'});async function load(){try{[rows.value,providers.value]=await Promise.all([teacherAPI.models(),teacherAPI.providers()]);const target=String(route.query.model||'');if(target){const row=rows.value.find(m=>m.id===target);if(row)await open(row)}}catch(e){error.value=msg(e)}}async function open(model:Model){try{selected.value=await teacherAPI.model(model.id);Object.assign(modelForm,selected.value.model);capability.value='';await router.replace({query:{model:model.id}})}catch(e){error.value=msg(e)}}function close(){selected.value=null;void router.replace({query:{}})}function addCapability(){const v=capability.value.trim();if(v&&!modelForm.capabilities.some(x=>x.toLowerCase()===v.toLowerCase()))modelForm.capabilities.push(v);capability.value=''}async function saveModel(){try{if(selected.value){const {model_id,...body}=modelForm;void model_id;const model=await teacherAPI.updateModel(selected.value.model.id,body);selected.value.model=model;toast.success('模型配置已更新')}else{await teacherAPI.createModel({model_id:modelForm.model_id,display_name:modelForm.display_name,description:modelForm.description,category:modelForm.category,capabilities:modelForm.capabilities,input_modalities:modelForm.input_modalities,output_modalities:modelForm.output_modalities,is_common:modelForm.is_common,status:'pending_configuration',...(modelForm.context_window===null?{}:{context_window:modelForm.context_window}),...(modelForm.max_output_tokens===null?{}:{max_output_tokens:modelForm.max_output_tokens})});createOpen.value=false;toast.success('模型已创建，状态为待配置')}await load()}catch(e){handle(e)}}function openBinding(binding?:Binding){editingBinding.value=binding??null;Object.assign(bindingForm,{provider_id:binding?.provider_id??'',upstream_model_name:binding?.upstream_model_name??'',adapter:binding?.adapter??'openai_compatible',priority:binding?.priority??100,status:binding?.status??'active'});bindingOpen.value=true}async function saveBinding(){if(!selected.value)return;try{if(editingBinding.value)await teacherAPI.updateBinding(editingBinding.value.id,{upstream_model_name:bindingForm.upstream_model_name,adapter:bindingForm.adapter,priority:bindingForm.priority,status:bindingForm.status});else await teacherAPI.createBinding(selected.value.model.id,bindingForm);selected.value=await teacherAPI.model(selected.value.model.id);bindingOpen.value=false;toast.success('Binding 已保存');await load()}catch(e){handle(e)}}async function toggle(model:Model){if(model.status==='active'&&!confirm('停用模型会影响使用该模型的 Key，是否继续？'))return;try{await teacherAPI.updateModel(model.id,{status:model.status==='active'?'inactive':'active'});await load()}catch(e){handle(e)}}function handle(e:unknown){if(e instanceof APIError&&e.code==='MODEL_ROUTING_REQUIRED'&&!Array.isArray(e.details))routingModels.value=e.details?.model_ids??[];else error.value=msg(e)}function msg(e:unknown){return e instanceof APIError?e.message:'请求失败'};onMounted(load);</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">TEACHER</p><h1>模型管理</h1><p class="muted">配置模型元数据、常用标记和供应商 Binding。</p></div><button class="button primary" @click="createOpen=true;Object.assign(modelForm,{model_id:'',display_name:'',description:'',category:'text',capabilities:[],input_modalities:[],output_modalities:[],context_window:null,max_output_tokens:null,is_common:false,status:'pending_configuration'})">新增模型</button></div><p v-if="error" class="error banner">{{error}}</p><section class="panel"><div class="segmented"><button :class="{active:tab==='common'}" @click="tab='common'">常用模型</button><button :class="{active:tab==='all'}" @click="tab='all'">所有模型 <span v-if="pending">{{pending}}</span></button></div><div class="grid two"><label>搜索<input v-model="query" placeholder="名称或 model_id"/></label><div class="row"><label>类别<select v-model="category"><option value="">全部</option><option v-for="v in ['text','image','audio','video','multimodal','embedding','rerank']" :key="v">{{v}}</option></select></label><label>状态<select v-model="status"><option value="">全部</option><option value="pending_configuration">待配置</option><option value="active">启用</option><option value="inactive">停用</option></select></label></div></div></section><div class="grid two" style="margin-top:20px"><article v-for="model in filtered" :key="model.id" class="panel"><div class="row"><div><strong>{{model.display_name}}</strong><p class="muted">{{model.model_id}} · {{model.category}}</p></div><StatusBadge :status="model.status"/></div><p class="muted">{{model.description||'暂无说明'}}</p><div class="chip-list"><span v-if="model.is_common" class="chip">常用</span><span class="chip">{{model.route_ready?'路由就绪':'路由未就绪'}}</span></div><div class="actions"><button class="button ghost" @click="open(model)">配置</button><button class="button" :class="model.status==='active'?'danger':'secondary'" :disabled="model.status!=='active'&&!model.route_ready" @click="toggle(model)">{{model.status==='active'?'停用':'启用'}}</button></div></article></div><AppDialog :open="Boolean(selected)||createOpen" :title="selected?selected.model.display_name:'新增模型'" wide @update:open="$event?null:(createOpen=false,close())"><form class="model-form" @submit.prevent="saveModel"><label>模型 ID<input v-model="modelForm.model_id" :readonly="Boolean(selected)" required/></label><div class="grid two"><label>显示名称<input v-model="modelForm.display_name" required/></label><label>类别<select v-model="modelForm.category"><option v-for="v in ['text','image','audio','video','multimodal','embedding','rerank']" :key="v">{{v}}</option></select></label></div><label>描述<textarea v-model="modelForm.description" rows="3"/></label><label>能力<div class="row"><input v-model="capability" @keydown.enter.prevent="addCapability"/><button type="button" class="button secondary" @click="addCapability">添加</button></div></label><div class="chip-list"><span v-for="v in modelForm.capabilities" :key="v" class="chip">{{v}}</span></div><div class="grid two"><fieldset class="modality-fieldset"><legend>输入模态</legend><div class="checkbox-list"><label v-for="v in ['text','image','audio','video']" :key="v" class="checkbox-option"><input v-model="modelForm.input_modalities" type="checkbox" :value="v"/><span>{{v}}</span></label></div></fieldset><fieldset class="modality-fieldset"><legend>输出模态</legend><div class="checkbox-list"><label v-for="v in ['text','image','audio','video']" :key="v" class="checkbox-option"><input v-model="modelForm.output_modalities" type="checkbox" :value="v"/><span>{{v}}</span></label></div></fieldset></div><div class="grid two"><label>上下文长度<input v-model.number="modelForm.context_window" type="number" min="1"/></label><label>最大输出 Token<input v-model.number="modelForm.max_output_tokens" type="number" min="1"/></label></div><label class="checkbox-option common-model-option"><input v-model="modelForm.is_common" type="checkbox"/><span>全局常用模型</span></label><div class="actions"><button class="button primary">保存基础配置</button></div></form><template v-if="selected"><hr/><div class="row"><h2>Bindings</h2><button class="button secondary" @click="openBinding()">新增 Binding</button></div><article v-for="binding in selected.bindings" :key="binding.id" class="list-row"><div><strong>{{binding.upstream_model_name}}</strong><p class="muted">{{binding.adapter}} · 优先级 {{binding.priority}}</p></div><div class="actions"><StatusBadge :status="binding.status"/><button class="button ghost" @click="openBinding(binding)">编辑</button></div></article></template></AppDialog><AppDialog :open="bindingOpen" :title="editingBinding?'编辑 Binding':'新增 Binding'" @update:open="bindingOpen=$event"><form @submit.prevent="saveBinding"><label v-if="!editingBinding">供应商<select v-model="bindingForm.provider_id" required><option value="">请选择</option><option v-for="p in providers" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>上游模型名<input v-model="bindingForm.upstream_model_name" required/></label><label>Adapter<select v-model="bindingForm.adapter"><option value="openai_compatible">OpenAI compatible</option><option value="anthropic">Anthropic</option></select></label><label>优先级<input v-model.number="bindingForm.priority" type="number" min="0" required/></label><label>状态<select v-model="bindingForm.status"><option value="active">启用</option><option value="inactive">停用</option></select></label><div class="actions"><button class="button primary">保存</button></div></form></AppDialog><AppDialog :open="Boolean(routingModels.length)" title="路由配置不足" @update:open="routingModels=$event?routingModels:[]"><p>以下 ACTIVE 模型会失去最后一条可用路由：</p><div class="chip-list"><span v-for="id in routingModels" :key="id" class="chip">{{id}}</span></div></AppDialog></section></template>
